 1: - name: Cluster {{ cluster_id }} - Create directories
 2:   file:
 3:     path: "{{ item }}"
 4:     state: directory
 5:     mode: 0755 # For some reason, item.mode converts 0755 into 493 ... weird
 6:   loop:
 7:     - clusters/{{ cluster_id }}
 8: 
 9: - name: Cluster {{ cluster_id }} - Create openshift-install configuration
10:   template:
11:     src: "{{ item.src }}"
12:     dest: "{{ item.dest }}"
13:   vars:
14:     ssh_pub_key: "{{ ssh_pub_key_task.stdout }}"
15:     pull_secret: "{{ lookup('file', './files/pull_secret.txt', errors='ignore') }}"
16:   with_items:
17:     - {
18:         src: templates/install-config.yaml.j2,
19:         dest: "clusters/{{ cluster_id }}/install-config.yaml",
20:       }
21:     - {
22:         src: templates/agent-config.yaml.j2,
23:         dest: "clusters/{{ cluster_id }}/agent-config.yaml",
24:       }
25:   register: okd_installer_config_files
26: 
27: # Let's create the proper OKD installation files (ignition, manifests, ...)
28: - name: Cluster {{ cluster_id }} - Run openshift-installer
29:   when: okd_installer_config_files.changed
30:   shell: |
31:     cd clusters/{{ cluster_id }}
32:     rm -rf install-dir
33:     mkdir install-dir
34:     cp install-config.yaml agent-config.yaml install-dir/
35:     {% if ipxe.enabled %}
36:       {% set cmd = "pxe-files" %}
37:     {% else %}
38:       {% set cmd = "image" %}
39:     {% endif %}
40:     openshift-install agent create {{ cmd }} --dir=install-dir
41:   environment:
42:     PATH: "/usr/local/bin:/usr/bin:/bin"
43:   register: installer_task
44: 
45: # Make these files available on the Web server
46: - name: Cluster {{ cluster_id }} - Copy boot-artifacts to www directory
47:   when: installer_task.changed
48:   become: true
49:   shell: |
50:     rm -rf /var/www/html/{{ cluster_id }}
51:     mkdir /var/www/html/{{ cluster_id }}
52:     {% if ipxe.enabled %}
53:     cp -R clusters/{{ cluster_id }}/install-dir/boot-artifacts/* /var/www/html/{{ cluster_id }}
54:     {% else %}
55:     cp clusters/{{ cluster_id }}/install-dir/agent.x86_64.iso /var/www/html/{{ cluster_id }}/
56:     {% endif %}
57:     chmod -R 755 /var/www/html/{{ cluster_id }}

  1: # yamllint disable rule:line-length
  2: ---
  3: # AWS S3 bucket (if 'cloud_backup_provider=aws')
  4: - name: "Set variable 'pgbackrest_conf' for backup in AWS S3 bucket"
  5:   ansible.builtin.set_fact:
  6:     pgbackrest_conf:
  7:       global:
  8:         - { option: "log-level-file", value: "detail" }
  9:         - { option: "log-path", value: "/var/log/pgbackrest" }
 10:         - { option: "repo1-type", value: "s3" }
 11:         - { option: "repo1-path", value: "{{ pgbackrest_repo_path | default('/pgbackrest') }}" }
 12:         - { option: "repo1-s3-key", value: "{{ pgbackrest_s3_key | default(lookup('ansible.builtin.env', 'AWS_ACCESS_KEY_ID')) }}" }
 13:         - { option: "repo1-s3-key-secret", value: "{{ pgbackrest_s3_key_secret | default(lookup('ansible.builtin.env', 'AWS_SECRET_ACCESS_KEY')) }}" }
 14:         - { option: "repo1-s3-bucket", value: "{{ pgbackrest_s3_bucket | default(aws_s3_bucket_name | default(patroni_cluster_name + '-backup')) }}" }
 15:         - {
 16:             option: "repo1-s3-endpoint",
 17:             value: "{{ pgbackrest_s3_endpoint | default('s3.' + (aws_s3_bucket_region | default(server_location)) + '.amazonaws.com') }}",
 18:           }
 19:         - { option: "repo1-s3-region", value: "{{ pgbackrest_s3_region | default(aws_s3_bucket_region | default(server_location)) }}" }
 20:         - { option: "repo1-retention-full", value: "{{ pgbackrest_retention_full | default('30') }}" }
 21:         - { option: "repo1-retention-full-type", value: "{{ pgbackrest_retention_full_type | default('time') }}" }
 22:         - { option: "repo1-bundle", value: "y" }
 23:         - { option: "repo1-block", value: "y" }
 24:         - { option: "start-fast", value: "y" }
 25:         - { option: "link-all", value: "y" }
 26:         - { option: "resume", value: "n" }
 27:         - { option: "archive-async", value: "y" }
 28:         - { option: "archive-get-queue-max", value: "1GiB" }
 29:         - { option: "spool-path", value: "/var/spool/pgbackrest" }
 30:         - { option: "process-max", value: "{{ pgbackrest_process_max | default([ansible_processor_vcpus | int // 2, 1] | max) }}" }
 31:         - { option: "backup-standby", value: "{{ 'y' if groups['postgres_cluster'] | length > 1 else 'n' }}" }
 32:       stanza:
 33:         - { option: "log-level-console", value: "info" }
 34:         - { option: "pg1-path", value: "{{ postgresql_data_dir }}" }
 35:   delegate_to: localhost
 36:   run_once: true # noqa run-once
 37:   no_log: true # do not output contents to the ansible log
 38:   when: cloud_backup_provider | default(cloud_provider | default('')) | lower == 'aws'
 39: 
 40: # GCS Bucket (if 'cloud_backup_provider=gcp')
 41: - name: "Set variable 'pgbackrest_conf' for backup in GCS Bucket"
 42:   ansible.builtin.set_fact:
 43:     pgbackrest_conf:
 44:       global:
 45:         - { option: "log-level-file", value: "detail" }
 46:         - { option: "log-path", value: "/var/log/pgbackrest" }
 47:         - { option: "repo1-type", value: "gcs" }
 48:         - { option: "repo1-path", value: "{{ pgbackrest_repo_path | default('/pgbackrest') }}" }
 49:         - { option: "repo1-gcs-key", value: "{{ pgbackrest_gcs_key | default(postgresql_home_dir + '/gcs-key.json') }}" }
 50:         - { option: "repo1-gcs-bucket", value: "{{ pgbackrest_gcs_bucket | default(gcp_bucket_name | default(patroni_cluster_name + '-backup')) }}" }
 51:         - { option: "repo1-retention-full", value: "{{ pgbackrest_retention_full | default('30') }}" }
 52:         - { option: "repo1-retention-full-type", value: "{{ pgbackrest_retention_full_type | default('time') }}" }
 53:         - { option: "repo1-bundle", value: "y" }
 54:         - { option: "repo1-block", value: "y" }
 55:         - { option: "start-fast", value: "y" }
 56:         - { option: "link-all", value: "y" }
 57:         - { option: "resume", value: "n" }
 58:         - { option: "archive-async", value: "y" }
 59:         - { option: "archive-get-queue-max", value: "1GiB" }
 60:         - { option: "spool-path", value: "/var/spool/pgbackrest" }
 61:         - { option: "process-max", value: "{{ pgbackrest_process_max | default([ansible_processor_vcpus | int // 2, 1] | max) }}" }
 62:         - { option: "backup-standby", value: "{{ 'y' if groups['postgres_cluster'] | length > 1 else 'n' }}" }
 63:       stanza:
 64:         - { option: "log-level-console", value: "info" }
 65:         - { option: "pg1-path", value: "{{ postgresql_data_dir }}" }
 66:   no_log: true # do not output contents to the ansible log
 67:   when: cloud_backup_provider | default(cloud_provider | default('')) | lower == 'gcp'
 68: 
 69: # Azure Blob Storage (if 'cloud_backup_provider=azure')
 70: - name: "Set variable 'pgbackrest_conf' for backup in Azure Blob Storage"
 71:   ansible.builtin.set_fact:
 72:     pgbackrest_conf:
 73:       global:
 74:         - { option: "log-level-file", value: "detail" }
 75:         - { option: "log-path", value: "/var/log/pgbackrest" }
 76:         - { option: "repo1-type", value: "azure" }
 77:         - { option: "repo1-path", value: "{{ pgbackrest_repo_path | default('/pgbackrest') }}" }
 78:         - { option: "repo1-azure-key", value: "{{ pgbackrest_azure_key | default(hostvars['localhost']['azure_storage_account_key'] | default('')) }}" }
 79:         - { option: "repo1-azure-key-type", value: "{{ pgbackrest_azure_key_type | default('shared') }}" }
 80:         - {
 81:             option: "repo1-azure-account",
 82:             value: "{{ pgbackrest_azure_account | default(azure_blob_storage_account_name | default(patroni_cluster_name | lower | replace('-', '') | truncate(24, true, ''))) }}",
 83:           }
 84:         - {
 85:             option: "repo1-azure-container",
 86:             value: "{{ pgbackrest_azure_container | default(azure_blob_storage_name | default(patroni_cluster_name + '-backup')) }}",
 87:           }
 88:         - { option: "repo1-retention-full", value: "{{ pgbackrest_retention_full | default('30') }}" }
 89:         - { option: "repo1-retention-full-type", value: "{{ pgbackrest_retention_full_type | default('time') }}" }
 90:         - { option: "repo1-bundle", value: "y" }
 91:         - { option: "repo1-block", value: "y" }
 92:         - { option: "start-fast", value: "y" }
 93:         - { option: "link-all", value: "y" }
 94:         - { option: "resume", value: "n" }
 95:         - { option: "archive-async", value: "y" }
 96:         - { option: "archive-get-queue-max", value: "1GiB" }
 97:         - { option: "spool-path", value: "/var/spool/pgbackrest" }
 98:         - { option: "process-max", value: "{{ pgbackrest_process_max | default([ansible_processor_vcpus | int // 2, 1] | max) }}" }
 99:         - { option: "backup-standby", value: "{{ 'y' if groups['postgres_cluster'] | length > 1 else 'n' }}" }
100:       stanza:
101:         - { option: "log-level-console", value: "info" }
102:         - { option: "pg1-path", value: "{{ postgresql_data_dir }}" }
103:   no_log: true # do not output contents to the ansible log
104:   when: cloud_backup_provider | default(cloud_provider | default('')) | lower == 'azure'
105: 
106: # DigitalOcean Spaces Object Storage (if 'cloud_backup_provider=digitalocean')
107: # Note: requires the Spaces access keys "AWS_ACCESS_KEY_ID" and "AWS_SECRET_ACCESS_KEY" (https://cloud.digitalocean.com/account/api/spaces)
108: - name: "Set variable 'pgbackrest_conf' for backup in DigitalOcean Spaces Object Storage"
109:   ansible.builtin.set_fact:
110:     pgbackrest_conf:
111:       global:
112:         - { option: "log-level-file", value: "detail" }
113:         - { option: "log-path", value: "/var/log/pgbackrest" }
114:         - { option: "repo1-type", value: "s3" }
115:         - { option: "repo1-path", value: "{{ pgbackrest_repo_path | default('/pgbackrest') }}" }
116:         - { option: "repo1-s3-key", value: "{{ pgbackrest_s3_key | default(digital_ocean_spaces_access_key | default(AWS_ACCESS_KEY_ID | default(''))) }}" }
117:         - { option: "repo1-s3-key-secret", value: "{{ pgbackrest_s3_key_secret | default(digital_ocean_spaces_secret_key | default(AWS_SECRET_ACCESS_KEY | default(''))) }}" }
118:         - { option: "repo1-s3-bucket", value: "{{ pgbackrest_s3_bucket | default(digital_ocean_spaces_name | default(patroni_cluster_name + '-backup')) }}" }
119:         - {
120:             option: "repo1-s3-endpoint",
121:             value: "{{ pgbackrest_s3_endpoint | default('https://' + (digital_ocean_spaces_region | default(default_region)) + '.digitaloceanspaces.com') }}",
122:           }
123:         - { option: "repo1-s3-region", value: "{{ pgbackrest_s3_region | default(digital_ocean_spaces_region | default(default_region)) }}" }
124:         - { option: "repo1-s3-uri-style", value: "{{ pgbackrest_s3_uri_style | default('path') }}" }
125:         - { option: "repo1-retention-full", value: "{{ pgbackrest_retention_full | default('30') }}" }
126:         - { option: "repo1-retention-full-type", value: "{{ pgbackrest_retention_full_type | default('time') }}" }
127:         - { option: "repo1-bundle", value: "y" }
128:         - { option: "repo1-block", value: "y" }
129:         - { option: "start-fast", value: "y" }
130:         - { option: "link-all", value: "y" }
131:         - { option: "resume", value: "n" }
132:         - { option: "archive-async", value: "y" }
133:         - { option: "archive-get-queue-max", value: "1GiB" }
134:         - { option: "spool-path", value: "/var/spool/pgbackrest" }
135:         - { option: "process-max", value: "{{ pgbackrest_process_max | default([ansible_processor_vcpus | int // 2, 1] | max) }}" }
136:         - { option: "backup-standby", value: "{{ 'y' if groups['postgres_cluster'] | length > 1 else 'n' }}" }
137:       stanza:
138:         - { option: "log-level-console", value: "info" }
139:         - { option: "pg1-path", value: "{{ postgresql_data_dir }}" }
140:   vars:
141:     default_region: "{{ (server_location in ['nyc1', 'nyc2']) | ternary('nyc3', server_location) }}"
142:   no_log: true # do not output contents to the ansible log
143:   when: cloud_backup_provider | default(cloud_provider | default('')) | lower == 'digitalocean'
144: 
145: # Hetzner Object Storage (if 'cloud_backup_provider=hetzner')
146: - name: "Set variable 'pgbackrest_conf' for backup in Hetzner Object Storage (S3 bucket)"
147:   ansible.builtin.set_fact:
148:     pgbackrest_conf:
149:       global:
150:         - { option: "log-level-file", value: "detail" }
151:         - { option: "log-path", value: "/var/log/pgbackrest" }
152:         - { option: "repo1-type", value: "s3" }
153:         - { option: "repo1-path", value: "{{ pgbackrest_repo_path | default('/pgbackrest') }}" }
154:         - { option: "repo1-s3-key", value: "{{ pgbackrest_s3_key | default(hetzner_object_storage_access_key | default('')) }}" }
155:         - { option: "repo1-s3-key-secret", value: "{{ pgbackrest_s3_key_secret | default(hetzner_object_storage_secret_key | default('')) }}" }
156:         - { option: "repo1-s3-bucket", value: "{{ pgbackrest_s3_bucket | default(hetzner_object_storage_name | default(patroni_cluster_name + '-backup')) }}" }
157:         - {
158:             option: "repo1-s3-endpoint",
159:             value: "{{ pgbackrest_s3_endpoint | default(hetzner_object_storage_endpoint | default('https://' + (hetzner_object_storage_region | default(default_region)) + '.your-objectstorage.com')) }}",
160:           }
161:         - { option: "repo1-s3-region", value: "{{ pgbackrest_s3_region | default(hetzner_object_storage_region | default(default_region)) }}" }
162:         - { option: "repo1-s3-uri-style", value: "{{ pgbackrest_s3_uri_style | default('path') }}" }
163:         - { option: "repo1-retention-full", value: "{{ pgbackrest_retention_full | default('30') }}" }
164:         - { option: "repo1-retention-full-type", value: "{{ pgbackrest_retention_full_type | default('time') }}" }
165:         - { option: "repo1-bundle", value: "y" }
166:         - { option: "repo1-block", value: "y" }
167:         - { option: "start-fast", value: "y" }
168:         - { option: "link-all", value: "y" }
169:         - { option: "resume", value: "n" }
170:         - { option: "archive-async", value: "y" }
171:         - { option: "archive-get-queue-max", value: "1GiB" }
172:         - { option: "spool-path", value: "/var/spool/pgbackrest" }
173:         - { option: "process-max", value: "{{ pgbackrest_process_max | default([ansible_processor_vcpus | int // 2, 1] | max) }}" }
174:         - { option: "backup-standby", value: "{{ 'y' if groups['postgres_cluster'] | length > 1 else 'n' }}" }
175:       stanza:
176:         - { option: "log-level-console", value: "info" }
177:         - { option: "pg1-path", value: "{{ postgresql_data_dir }}" }
178:   vars:
179:     default_region: "{{ (server_location in ['hel1', 'fsn1', 'nbg1']) | ternary(server_location, 'nbg1') }}"
180:   delegate_to: localhost
181:   run_once: true # noqa run-once
182:   no_log: true # do not output contents to the ansible log
183:   when: cloud_backup_provider | default(cloud_provider | default('')) | lower == 'hetzner'

